parameters.jsCode:
const body = $input.first().json;

if (body.error) {
  return [{ json: { reply: `Sorry, something went wrong talking to the assistant: ${body.error.message || JSON.stringify(body.error)}` } }];
}

const content = body.content || [];
const text = content
  .filter((b) => b.type === 'text')
  .map((b) => b.text)
  .join('\n\n')
  .trim();

return [{ json: { reply: text || "Sorry, I couldn't generate a response." } }];
